571 :                 // of the path
572 :                 if (parent instanceof DOMNodePointer) {
573 :                     if (buffer.length() == 0
574 :                             || buffer.charAt(buffer.length() - 1) != '/') {
575 :                         buffer.append('/');
576 :                     }
577 :                     String ln = DOMNodePointer.getLocalName(node);
578 :                     String nsURI = getNamespaceURI();
579 :                     if (nsURI == null) {
580 :                         buffer.append(ln);
581 :                         buffer.append('[');
582 :                         buffer.append(getRelativePositionByName()).append(']');
583 :                     }
584 :                     else {
585 :                         String prefix = getNamespaceResolver().getPrefix(nsURI);
586 :                         if (prefix != null) {
587 :                             buffer.append(prefix);
588 :                             buffer.append(':');
589 :                             buffer.append(ln);
590 :                             buffer.append('[');
591 :                             buffer.append(getRelativePositionByName());
592 :                             buffer.append(']');
593 :                         }
594 :                         else {
595 :                             buffer.append("node()");
596 :                             buffer.append('[');
597 :                             buffer.append(getRelativePositionOfElement());
598 :                             buffer.append(']');
599 :                         }
600 :                     }
601 :                 }
602 :             break;
603 :             case Node.TEXT_NODE :
604 :             case Node.CDATA_SECTION_NODE :
605 :                 buffer.append("/text()");
606 :                 buffer.append('[');
607 :                 buffer.append(getRelativePositionOfTextNode()).append(']');
608 :                 break;
609 :             case Node.PROCESSING_INSTRUCTION_NODE :
610 :                 buffer.append("/processing-instruction(\'");
611 :                 buffer.append(((ProcessingInstruction) node).getTarget()).append("')");
612 :                 buffer.append('[');
613 :                 buffer.append(getRelativePositionOfPI()).append(']');
614 :                 break;
615 :             case Node.DOCUMENT_NODE :
616 :                 // That'll be empty
617 :         }
618 :         return buffer.toString();
619 :     }"

"876 :     public int compareChildNodePointers(
877 :             NodePointer pointer1, NodePointer pointer2)
878 :     {
879 :         Node node1 = (Node) pointer1.getBaseValue();
880 :         Node node2 = (Node) pointer2.getBaseValue();
881 :         if (node1 == node2) {
882 :             return 0;
883 :         }
884 : 
885 :         int t1 = node1.getNodeType();
886 :         int t2 = node2.getNodeType();
887 :         if (t1 == Node.ATTRIBUTE_NODE && t2 != Node.ATTRIBUTE_NODE) {
888 :             return -1;
889 :         }
890 :         if (t1 != Node.ATTRIBUTE_NODE && t2 == Node.ATTRIBUTE_NODE) {
891 :             return 1;
892 :         }
893 :         if (t1 == Node.ATTRIBUTE_NODE && t2 == Node.ATTRIBUTE_NODE) {
894 :             NamedNodeMap map = ((Node) getNode()).getAttributes();
895 :             int length = map.getLength();
896 :             for (int i = 0; i < length; i++) {
897 :                 Node n = map.item(i);
898 :                 if (n == node1) {
899 :                     return -1;
900 :                 }
901 :                 if (n == node2) {
902 :                     return 1;
903 :                 }
904 :             }
905 :             return 0; // Should not happen
906 :         }
907 : 
908 :         Node current = node.getFirstChild();
909 :         while (current != null) {
910 :             if (current == node1) {
911 :                 return -1;
912 :             }
913 :             if (current == node2) {
914 :                 return 1;
915 :             }
916 :             current = current.getNextSibling();
917 :         }
918 :         return 0;
919 :     }"

